package com.rezkery.randomizer;

import android.app.*;
import android.content.*;
import android.os.Bundle;
import org.json.*;
import java.util.concurrent.*;

/** Runs against an isolated emulator. No real site or account is contacted. */
public final class SuiteSmokeInstrumentation extends Instrumentation {
    @Override public void onCreate(Bundle b){super.onCreate(b);start();}
    void check(boolean ok,String message){if(!ok)throw new AssertionError(message);}
    String js(SuiteActivity a,String expression)throws Exception{CountDownLatch latch=new CountDownLatch(1);String[] result={null};runOnMainSync(()->a.view.evaluateJavascript(expression,value->{result[0]=value;latch.countDown();}));if(!latch.await(10,TimeUnit.SECONDS))throw new Exception("WebView callback timed out");return result[0];}
    String siteJs(SuiteActivity a,String expression)throws Exception{CountDownLatch latch=new CountDownLatch(1);String[] result={null};runOnMainSync(()->a.site.evaluateJavascript(expression,value->{result[0]=value;latch.countDown();}));if(!latch.await(10,TimeUnit.SECONDS))throw new Exception("Site WebView callback timed out");return result[0];}
    void keyboard(SuiteActivity a)throws Exception{
        runOnMainSync(()->{a.ensureSite();a.view.setVisibility(android.view.View.GONE);a.siteBox.setVisibility(android.view.View.VISIBLE);a.site.loadDataWithBaseURL("https://keyboard-fixture.invalid/","<html><meta name='viewport' content='width=device-width, initial-scale=1'><body><input id='login' style='font-size:20px;width:90%;height:60px;margin:20px' placeholder='Test login'></body></html>","text/html","UTF-8",null);});
        JSONObject rect=null;for(int n=0;n<30;n++){Thread.sleep(200);String value=siteJs(a,"document.getElementById('login')?JSON.stringify((()=>{const r=document.getElementById('login').getBoundingClientRect();return {x:r.x+r.width/2,y:r.y+r.height/2,dpr:devicePixelRatio}})()):null");Object decoded=new JSONTokener(value).nextValue();if(decoded instanceof String){rect=new JSONObject((String)decoded);break;}}check(rect!=null,"Login input fixture");
        int[] location=new int[2];runOnMainSync(()->a.site.getLocationOnScreen(location));float x=location[0]+(float)(rect.getDouble("x")*rect.getDouble("dpr")),y=location[1]+(float)(rect.getDouble("y")*rect.getDouble("dpr"));long time=android.os.SystemClock.uptimeMillis();android.view.MotionEvent down=android.view.MotionEvent.obtain(time,time,android.view.MotionEvent.ACTION_DOWN,x,y,0),up=android.view.MotionEvent.obtain(time,time+100,android.view.MotionEvent.ACTION_UP,x,y,0);sendPointerSync(down);sendPointerSync(up);down.recycle();up.recycle();
        boolean[] visible={false};for(int n=0;n<20&&!visible[0];n++){Thread.sleep(200);runOnMainSync(()->{android.view.WindowInsets insets=a.root.getRootWindowInsets();visible[0]=insets!=null&&insets.isVisible(android.view.WindowInsets.Type.ime());});}check(visible[0],"Android virtual keyboard must be visible after tapping login input");sendStringSync("suite-test");Thread.sleep(200);check("suite-test".equals(new JSONTokener(siteJs(a,"document.getElementById('login').value")).nextValue()),"Login text input");check("undefined".equals(new JSONTokener(siteJs(a,"typeof RezkaNative")).nextValue()),"Site WebView must not expose the native bridge");
    }
    @Override public void onStart(){Bundle result=new Bundle();SuiteActivity activity=null;try{
        SuiteDatabase db=new SuiteDatabase(getTargetContext());long started=System.currentTimeMillis();StringBuilder measurements=new StringBuilder();
        for(int size=0;size<100000;size+=500){JSONArray rows=new JSONArray();for(int n=size;n<size+500;n++){JSONObject m=new JSONObject().put("id","rezka:"+(1000000+n)).put("url","https://rezka.fi/films/"+(1000000+n)+"-synthetic.html").put("title","Synthetic "+n).put("search","synthetic "+n).put("year",1980+n%40).put("type",n%4==0?"series":"film").put("status","").put("rating",0).put("addedAt",n);rows.put(new JSONArray().put("movies").put(m));}db.command(new JSONObject().put("op","batch").put("rows",rows));if(size+500==10000||size+500==50000||size+500==100000){long t=System.currentTimeMillis();JSONObject page=(JSONObject)db.command(new JSONObject().put("op","query").put("filters",new JSONObject().put("year","1990").put("q","synthetic").put("type","film").put("limit",60)));check(page.getJSONArray("items").length()==60,"SQLite filtered page");measurements.append(size+500).append(" records: query ").append(System.currentTimeMillis()-t).append(" ms; ");}}
        JSONObject user=new JSONObject().put("id","rezka:1000000").put("note","Проверка заметки");db.command(new JSONObject().put("op","batch").put("rows",new JSONArray().put(new JSONArray().put("userState").put(user))));check(((JSONObject)db.command(new JSONObject().put("op","get").put("store","userState").put("id",user.getString("id")))).getString("note").equals("Проверка заметки"),"SQLite note roundtrip");db.close();
        SuiteDatabase files=new SuiteDatabase(getTargetContext());JSONObject poster=new JSONObject().put("id","image:rollback-test").put("data","data:image/png;base64,AAAA");files.command(new JSONObject().put("op","batch").put("rows",new JSONArray().put(new JSONArray().put("assets").put(poster))));boolean rejected=false;try{files.command(new JSONObject().put("op","batch").put("rows",new JSONArray().put(new JSONArray().put("assets").put(new JSONObject().put("id",poster.getString("id"))).put(true)).put(new JSONArray().put("invalid-store").put(new JSONObject().put("id","test")))));}catch(Exception expected){rejected=true;}check(rejected,"Invalid batch must roll back");check(((JSONObject)files.command(new JSONObject().put("op","get").put("store","assets").put("id",poster.getString("id")))).getString("data").equals(poster.getString("data")),"Media must survive rolled-back deletion");files.close();
        Intent i=new Intent(getTargetContext(),SuiteActivity.class);i.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);activity=(SuiteActivity)startActivitySync(i);boolean ready=false;for(int n=0;n<40;n++){Thread.sleep(500);String value=js(activity,"JSON.stringify({stats:document.querySelector('#stats')?.textContent,message:document.querySelector('#message')?.textContent,cards:document.querySelectorAll('#cards .movie').length,bridge:typeof RezkaNative})");Object decoded=new JSONTokener(value).nextValue();if(decoded instanceof String){JSONObject state=new JSONObject((String)decoded);check(!state.optString("message").startsWith("Не удалось"),state.optString("message"));if(state.optInt("cards")==60){check(state.getString("stats").contains("100000"),"Native UI count");ready=true;break;}}}check(ready,"Native WebView library did not render");
        js(activity,"document.querySelector('[data-tab=files]').click();document.querySelector('#theme').click();true");check(js(activity,"document.querySelector('#files').hidden").equals("false"),"Native navigation");
        keyboard(activity);result.putString("stream","SUITE_SMOKE_OK · SUITE_IME_OK · "+measurements+" total "+(System.currentTimeMillis()-started)+" ms\n");finish(Activity.RESULT_OK,result);
    }catch(Throwable e){result.putString("stream","SUITE_SMOKE_FAILED: "+e+"\n");finish(Activity.RESULT_CANCELED,result);}finally{if(activity!=null){SuiteActivity current=activity;runOnMainSync(current::finish);}}}
}
